                    rr, cc = r - dist, c + w
                elif o == 1:  # East
                    rr, cc = r + w, c + dist
                elif o == 2:  # South
                    rr, cc = r + dist, c + w
                elif o == 3:  # West
                    rr, cc = r + w, c - dist
                cells.append((rr, cc))
        return cells

    # Helper to count how much actual waste would be eliminated by firing
    def count_waste(r, c, o):
        cnt = 0
        for rr, cc in get_clean_area(r, c, o):
