        result = bfs_nearest_apple(env, agent_id)
        if result is not None:
            dr, dc = result
            return int(direction_to_action(dr, dc, orient))
        else:
            # If no apples are currently available, tactically spread/wait in the orchard area
            if c < 12:
                orchard_cells = set()
                for r_idx in range(env.height):
